package ir.alirezaivaz.mygarage;

import android.app.*;
import android.os.*;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
    static final int GOLD=Color.rgb(211,174,102), BG=Color.rgb(16,17,20), CARD=Color.rgb(31,32,36), TEXT=Color.rgb(244,240,230), MUTED=Color.rgb(164,160,150);
    DB db; LinearLayout root, body; boolean dark=true; int carId=1; TextView mileageValue, statusValue;
    static final int EXPORT=91, IMPORT=92;
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);db=new DB(this);dark=getPreferences(0).getBoolean("dark",true);ensureCar();createChannel();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);scheduleDaily();home();}
    void ensureCar(){if(db.count("cars")==0){ContentValues v=new ContentValues();v.put("name","پژو ۲۰۶");v.put("model","۲۰۶");v.put("km",0);db.getWritableDatabase().insert("cars",null,v);}carId=db.firstCar();}
    int colorBg(){return dark?BG:Color.rgb(242,240,235);} int colorCard(){return dark?CARD:Color.WHITE;} int colorText(){return dark?TEXT:Color.rgb(37,38,40);} int colorMuted(){return dark?MUTED:Color.rgb(115,112,105);}
    GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(22));d.setStroke(dp(1),stroke);return d;}
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(colorText());if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    void pad(View v,int a){v.setPadding(dp(a),dp(a),dp(a),dp(a));}
    TextView button(String label,Runnable action){TextView t=text(label,14,true);t.setGravity(Gravity.CENTER);t.setTextColor(dark?TEXT:Color.rgb(55,45,25));t.setBackground(shape(dark?Color.rgb(91,72,42):Color.rgb(235,218,180),GOLD));t.setPadding(dp(16),dp(13),dp(16),dp(13));t.setOnClickListener(v->action.run());return t;}
    LinearLayout card(){LinearLayout c=column();c.setPadding(dp(18),dp(17),dp(18),dp(17));c.setBackground(shape(colorCard(),dark?Color.rgb(72,62,45):Color.rgb(225,215,195)));return c;}
    void shell(String title){root=column();root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.setBackgroundColor(colorBg());setContentView(root);LinearLayout header=row();header.setPadding(dp(20),dp(18),dp(20),dp(12));TextView h=text(title,23,true);header.addView(h,new LinearLayout.LayoutParams(0,-2,1));TextView theme=button(dark?"☼":"☾",()->{dark=!dark;getPreferences(0).edit().putBoolean("dark",dark).apply();home();});header.addView(theme);root.addView(header);ScrollView sc=new ScrollView(this);body=column();body.setPadding(dp(16),dp(8),dp(16),dp(28));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
    void gap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    void home(){shell("گاراژ من");SQLiteDatabase sql=db.getReadableDatabase();Cursor c=sql.rawQuery("SELECT name,model,km FROM cars WHERE id=?",new String[]{""+carId});String name="خودروی من",model="";int km=0;if(c.moveToFirst()){name=c.getString(0);model=c.getString(1);km=c.getInt(2);}c.close();
        LinearLayout hero=card();hero.setBackground(shape(dark?Color.rgb(48,42,32):Color.rgb(250,245,233),GOLD));TextView eyebrow=text("مدیریت هوشمند خودرو",12,false);eyebrow.setTextColor(GOLD);hero.addView(eyebrow);gap(hero,7);TextView car=text(name+"  "+model,22,true);hero.addView(car);gap(hero,15);TextView kmv=text(String.format(Locale.US,"%,d",km)+" کیلومتر",30,true);kmv.setTextColor(GOLD);hero.addView(kmv);gap(hero,12);LinearLayout actions=row();actions.addView(button("ویرایش کیلومتر",()->editMileage()),new LinearLayout.LayoutParams(0,-2,1));View spacer=new View(this);actions.addView(spacer,new LinearLayout.LayoutParams(dp(8),1));actions.addView(button("ویرایش خودرو",()->editCar()),new LinearLayout.LayoutParams(0,-2,1));hero.addView(actions);body.addView(hero);
        gap(body,16);LinearLayout summary=card();summary.addView(text("وضعیت سرویس‌ها",17,true));gap(summary,8);int overdue=db.dueCount(km);TextView st=text(overdue==0?"همه‌چیز مرتب است":"موعد سرویس‌ها را بررسی کنید",14,false);st.setTextColor(overdue==0?GOLD:Color.rgb(220,135,90));summary.addView(st);body.addView(summary);
        gap(body,16);TextView section=text("دسترسی سریع",18,true);body.addView(section);gap(body,10);LinearLayout grid=row();grid.addView(button("＋ ثبت سرویس",()->addService()),new LinearLayout.LayoutParams(0,-2,1));View s=new View(this);grid.addView(s,new LinearLayout.LayoutParams(dp(8),1));grid.addView(button("◷ برنامه سرویس",()->services()),new LinearLayout.LayoutParams(0,-2,1));body.addView(grid);gap(body,9);LinearLayout grid2=row();grid2.addView(button("خروجی پشتیبان",()->exportBackup()),new LinearLayout.LayoutParams(0,-2,1));View s2=new View(this);grid2.addView(s2,new LinearLayout.LayoutParams(dp(8),1));grid2.addView(button("بازیابی پشتیبان",()->importBackup()),new LinearLayout.LayoutParams(0,-2,1));body.addView(grid2);
        gap(body,20);body.addView(text("سرویس‌های نزدیک",18,true));gap(body,8);showServices(body,km);gap(body,20);body.addView(button("مدیریت کامل سرویس‌ها",()->services()));}
    void editMileage(){EditText e=field("کیلومتر فعلی");e.setInputType(2);e.setText(""+db.carKm(carId));new AlertDialog.Builder(this).setTitle("به‌روزرسانی کیلومتر").setView(wrap(e)).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(d,w)->{try{int k=Integer.parseInt(e.getText().toString());ContentValues v=new ContentValues();v.put("km",k);db.getWritableDatabase().update("cars",v,"id=?",new String[]{""+carId});home();}catch(Exception ex){toast("عدد کیلومتر معتبر نیست");}}).show();}
    void editCar(){EditText n=field("نام خودرو (مثلاً پژو ۲۰۶)"),m=field("مدل"),k=field("کیلومتر فعلی");n.setText(db.carName(carId));m.setText(db.carModel(carId));k.setText(""+db.carKm(carId));k.setInputType(2);LinearLayout box=column();box.addView(n);box.addView(m);box.addView(k);new AlertDialog.Builder(this).setTitle("ویرایش خودرو").setView(wrap(box)).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(d,w)->{ContentValues v=new ContentValues();v.put("name",n.getText().toString());v.put("model",m.getText().toString());try{v.put("km",Integer.parseInt(k.getText().toString()));}catch(Exception ex){}db.getWritableDatabase().update("cars",v,"id=?",new String[]{""+carId});home();}).show();}
    EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(colorText());e.setHintTextColor(colorMuted());e.setGravity(Gravity.RIGHT);e.setPadding(dp(12),dp(9),dp(12),dp(9));e.setBackground(shape(colorBg(),GOLD));return e;}
    View wrap(View v){LinearLayout l=column();l.setPadding(dp(20),dp(8),dp(20),dp(4));l.addView(v);return l;}
    void addService(){EditText name=field("نام سرویس؛ مثل تعویض روغن"),km=field("کیلومتر سرویس بعدی (اختیاری)"),date=field("تاریخ سررسید (اختیاری: YYYY-MM-DD)");km.setInputType(2);LinearLayout box=column();box.addView(name);box.addView(km);box.addView(date);new AlertDialog.Builder(this).setTitle("افزودن سرویس").setView(wrap(box)).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(d,w)->{if(name.getText().toString().trim().isEmpty()){toast("نام سرویس را وارد کنید");return;}ContentValues v=new ContentValues();v.put("car_id",carId);v.put("name",name.getText().toString().trim());try{v.put("due_km",km.getText().toString().isEmpty()?0:Integer.parseInt(km.getText().toString()));}catch(Exception ex){v.put("due_km",0);}v.put("due_date",date.getText().toString().trim());v.put("done",0);db.getWritableDatabase().insert("services",null,v);scheduleDaily();home();}).show();}
    void services(){shell("برنامه سرویس‌ها");body.addView(button("＋ افزودن سرویس جدید",()->addService()));gap(body,14);showServices(body,db.carKm(carId));}
    void showServices(LinearLayout target,int km){Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,due_km,due_date,done FROM services WHERE car_id=? ORDER BY done ASC,id DESC",new String[]{""+carId});if(c.getCount()==0){target.addView(text("هنوز سرویسی ثبت نشده است.",14,false));}while(c.moveToNext()){int id=c.getInt(0),due=c.getInt(2),done=c.getInt(4);String name=c.getString(1),date=c.getString(3);LinearLayout item=card();TextView title=text(name,16,true);item.addView(title);gap(item,5);String detail=(due>0?"موعد کیلومتری: "+String.format(Locale.US,"%,d",due)+" · ":"")+(date==null||date.isEmpty()?"بدون تاریخ": "تاریخ: "+date);TextView sub=text(detail,12,false);sub.setTextColor(colorMuted());item.addView(sub);gap(item,8);TextView state=text(done==1?"انجام‌شده":due>0&&km>=due?"سررسید گذشته":"در برنامه",12,true);state.setTextColor(done==1?GOLD:(due>0&&km>=due?Color.rgb(220,120,90):colorMuted()));item.addView(state);gap(item,9);LinearLayout buttons=row();buttons.addView(button(done==1?"فعال‌سازی مجدد":"ثبت انجام سرویس",()->{ContentValues v=new ContentValues();v.put("done",done==1?0:1);db.getWritableDatabase().update("services",v,"id=?",new String[]{""+id});services();}),new LinearLayout.LayoutParams(0,-2,1));View gap=new View(this);buttons.addView(gap,new LinearLayout.LayoutParams(dp(8),1));buttons.addView(button("حذف",()->new AlertDialog.Builder(this).setMessage("این سرویس حذف شود؟").setNegativeButton("نه",null).setPositiveButton("حذف",(a,b)->{db.getWritableDatabase().delete("services","id=?",new String[]{""+id});services();}).show()),new LinearLayout.LayoutParams(0,-2,1));item.addView(buttons);target.addView(item);gap(target,9);}c.close();}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("service_due","یادآوری سرویس خودرو",NotificationManager.IMPORTANCE_DEFAULT);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);}}
    void scheduleDaily(){Intent i=new Intent(this,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(this,10,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,9);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<System.currentTimeMillis())c.add(Calendar.DAY_OF_YEAR,1);AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);if(a!=null)a.setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);}
    public static class ReminderReceiver extends BroadcastReceiver {public void onReceive(Context ctx,Intent i){DB db=new DB(ctx);int km=db.carKm(db.firstCar());Cursor c=db.getReadableDatabase().rawQuery("SELECT name,due_km,due_date FROM services WHERE done=0",null);ArrayList<String> due=new ArrayList<>();long now=System.currentTimeMillis();while(c.moveToNext()){int dk=c.getInt(1);String date=c.getString(2);boolean soon=dk>0&&km>=dk-500;try{if(date!=null&&!date.isEmpty()){long t=new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(date).getTime();soon|=t-now<14L*86400000&&t-now>=-86400000;}}catch(Exception e){}if(soon)due.add(c.getString(0));}c.close();if(!due.isEmpty()){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(ctx,"service_due"):new Notification.Builder(ctx);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("یادآوری سرویس خودرو").setContentText("موعد سرویس: "+due.get(0)+(due.size()>1?" و "+(due.size()-1)+" مورد دیگر":"")).setAutoCancel(true);((NotificationManager)ctx.getSystemService(Context.NOTIFICATION_SERVICE)).notify(33,b.build());}}}
    public static class BootReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){Intent x=new Intent(c,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(c,10,x,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar t=Calendar.getInstance();t.set(Calendar.HOUR_OF_DAY,9);t.set(Calendar.MINUTE,0);AlarmManager a=(AlarmManager)c.getSystemService(ALARM_SERVICE);if(a!=null)a.setInexactRepeating(AlarmManager.RTC_WAKEUP,t.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);}}
    void exportBackup(){try{JSONObject root=new JSONObject();root.put("format","mygarage-backup");root.put("version",1);root.put("cars",db.readTable("cars"));root.put("services",db.readTable("services"));Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"mygarage-backup.json");startActivityForResult(i,EXPORT);backupPending=root;}catch(Exception e){toast("ساخت پشتیبان ناموفق بود");}}
    JSONObject backupPending;
    void importBackup(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null)return;try{if(req==EXPORT&&backupPending!=null){OutputStream o=getContentResolver().openOutputStream(data.getData());o.write(backupPending.toString(2).getBytes("UTF-8"));o.close();toast("پشتیبان ذخیره شد");}else if(req==IMPORT){InputStream in=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)b.write(buf,0,n);in.close();JSONObject j=new JSONObject(b.toString("UTF-8"));if(!"mygarage-backup".equals(j.optString("format")))throw new Exception();new AlertDialog.Builder(this).setTitle("جایگزینی اطلاعات؟").setMessage("اطلاعات فعلی با پشتیبان جایگزین می‌شود.").setNegativeButton("انصراف",null).setPositiveButton("بازیابی",(d,w)->{db.restore(j);ensureCar();home();toast("بازیابی انجام شد");}).show();}}catch(Exception e){toast("فایل پشتیبان معتبر نیست");}}
    static class DB extends SQLiteOpenHelper {
        DB(Context c){super(c,"mygarage_local.db",null,1);}
        public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE cars(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,model TEXT,km INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE services(id INTEGER PRIMARY KEY AUTOINCREMENT,car_id INTEGER,name TEXT,due_km INTEGER DEFAULT 0,due_date TEXT,done INTEGER DEFAULT 0)");}
        public void onUpgrade(SQLiteDatabase d,int a,int b){}
        int count(String t){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM "+t,null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}
        int firstCar(){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM cars ORDER BY id LIMIT 1",null);int n=c.moveToFirst()?c.getInt(0):1;c.close();return n;}
        int carKm(int id){Cursor c=getReadableDatabase().rawQuery("SELECT km FROM cars WHERE id=?",new String[]{""+id});int n=c.moveToFirst()?c.getInt(0):0;c.close();return n;}
        String carName(int id){return carField(id,"name");}String carModel(int id){return carField(id,"model");}
        String carField(int id,String f){Cursor c=getReadableDatabase().rawQuery("SELECT "+f+" FROM cars WHERE id=?",new String[]{""+id});String s=c.moveToFirst()?c.getString(0):"";c.close();return s==null?"":s;}
        int dueCount(int km){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM services WHERE done=0 AND due_km>0 AND due_km<=?",new String[]{""+km});c.moveToFirst();int n=c.getInt(0);c.close();return n;}
        JSONArray readTable(String t)throws Exception{JSONArray a=new JSONArray();Cursor c=getReadableDatabase().rawQuery("SELECT * FROM "+t,null);while(c.moveToNext()){JSONObject o=new JSONObject();for(int i=0;i<c.getColumnCount();i++)o.put(c.getColumnName(i),c.getString(i));a.put(o);}c.close();return a;}
        void restore(JSONObject j){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{d.delete("services",null,null);d.delete("cars",null,null);JSONArray cars=j.getJSONArray("cars");for(int i=0;i<cars.length();i++){JSONObject o=cars.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",o.optInt("id"));v.put("name",o.optString("name"));v.put("model",o.optString("model"));v.put("km",o.optInt("km"));d.insert("cars",null,v);}JSONArray ss=j.getJSONArray("services");for(int i=0;i<ss.length();i++){JSONObject o=ss.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",o.optInt("id"));v.put("car_id",o.optInt("car_id"));v.put("name",o.optString("name"));v.put("due_km",o.optInt("due_km"));v.put("due_date",o.optString("due_date"));v.put("done",o.optInt("done"));d.insert("services",null,v);}d.setTransactionSuccessful();}catch(Exception e){}finally{d.endTransaction();}}
    }
}